#ifndef CAREBRIDGE_APPLICATION_HPP
#define CAREBRIDGE_APPLICATION_HPP
#include "../storage/store.hpp"
#include "../domain/healthcare.hpp"
#include <cmath>
#include <map>

namespace carebridge {
struct ApplicationError:std::runtime_error{int status;ApplicationError(int s,const std::string&m):std::runtime_error(m),status(s){}};
class HealthcareApplication {
    Store& store_;
    std::string field(const Json&j,const std::string&key,std::size_t max=4096)const{if(!j.is_object()||!j.contains(key)||!j[key].is_string())throw ApplicationError(422,"Missing or invalid field: "+key);std::string v=j[key].get<std::string>();if(v.empty()||v.size()>max)throw ApplicationError(422,"Invalid field: "+key);return v;}
    bool consent(const std::string&p,const std::string&d,const std::string&s)const{for(const Json&c:store_.list("consents"))if(c.value("patient_id",std::string())==p&&c.value("doctor_id",std::string())==d&&c.value("scope",std::string())==s&&(c.value("status",std::string())=="granted"||c.value("status",std::string())=="active"))return true;return false;}
    Json assigned(const Json&t,const std::string&id)const{Json o=store_.findAssignedLabOrder(id,t.value("id",std::string()),t.value("department",std::string()));if(o.is_null()){try{store_.audit(t.value("id",std::string()),t.value("role",std::string()),"lab_order.access",id,false,"unassigned or department mismatch");}catch(...){}throw ApplicationError(403,"Investigation is not assigned to this technician");}return o;}
public:
    explicit HealthcareApplication(Store&s):store_(s){}
    static std::string appointmentStatus(const Json&a,const std::string&next){try{Appointment d(a.value("id",std::string()),a.value("patient_id",std::string()),a.value("doctor_id",std::string()),a.value("status",std::string()));d.transition(next);return d.status();}catch(const std::exception&e){throw ApplicationError(409,e.what());}}
    Json technicians(const Json&doctor)const{if(doctor.value("role",std::string())!="doctor")throw ApplicationError(403,"Doctor role required");Json out=Json::array();for(const Json&u:store_.list("users"))if(u.value("role",std::string())=="lab_technician")out.push_back(Json{{"id",u["id"]},{"full_name",u["full_name"]},{"department",u["department"]}});return out;}
    Json createLabOrder(const Json&doctor,const std::string&patientId,const Json&j){if(doctor.value("role",std::string())!="doctor")throw ApplicationError(403,"Doctor role required");if(!consent(patientId,doctor.value("id",std::string()),"medical_history"))throw ApplicationError(403,"Patient consent required to request investigation");Json patient=store_.find("patients",patientId);if(patient.is_null())throw ApplicationError(404,"Patient not found");std::string test=field(j,"test_name",60),techId=field(j,"technician_id",80),dept=field(j,"department",80);if(test!="CBC"&&test!="Haemoglobin"&&test!="WBC"&&test!="Platelets")throw ApplicationError(400,"Unsupported laboratory test");Json tech;for(const Json&u:store_.list("users"))if(u.value("id",std::string())==techId){tech=u;break;}if(tech.is_null()||tech.value("role",std::string())!="lab_technician"||tech.value("department",std::string())!=dept)throw ApplicationError(400,"Technician must be provisioned for the requested department");std::string id=newId();LaboratoryOrder domain(id,patientId,doctor.value("id",std::string()),dept,test);try{domain.assign(techId);}catch(const std::exception&e){throw ApplicationError(409,e.what());}Json order={{"id",id},{"patient_id",patientId},{"patient_user_id",patient["user_id"]},{"doctor_id",doctor["id"]},{"technician_id",techId},{"department",dept},{"test_name",test},{"purpose","Clinician-requested laboratory investigation"},{"status",domain.status()},{"created_at",timestamp()}};store_.insert("lab_orders",order);store_.audit(doctor.value("id",std::string()),"doctor","lab_order.create",id,true,"");return order;}
    Json assignedOrders(const Json&tech)const{if(tech.value("role",std::string())!="lab_technician")throw ApplicationError(403,"Laboratory technician role required");Json out=Json::array();for(const Json&o:store_.list("lab_orders"))if(o.value("technician_id",std::string())==tech.value("id",std::string())&&o.value("department",std::string())==tech.value("department",std::string()))out.push_back(o);return out;}
    Json labOrderDetails(const Json&tech,const std::string&id){Json o=assigned(tech,id),p=store_.find("patients",o.value("patient_id",std::string())),u=Json();for(const Json&x:store_.list("users"))if(x.value("id",std::string())==p.value("user_id",std::string())){u=x;break;}store_.audit(tech.value("id",std::string()),"lab_technician","lab_order.read",id,true,"");return Json{{"id",o["id"]},{"patient_id",o["patient_id"]},{"patient_name",u.value("full_name",std::string())},{"department",o["department"]},{"test_name",o["test_name"]},{"purpose",o["purpose"]},{"status",o["status"]},{"created_at",o["created_at"]}};}
    Json startLabOrder(const Json&tech,const std::string&id){Json o=assigned(tech,id);try{LaboratoryOrder d(id,o.value("patient_id",std::string()),o.value("doctor_id",std::string()),o.value("department",std::string()),o.value("test_name",std::string()),o.value("status",std::string()),o.value("technician_id",std::string()));d.begin(tech.value("id",std::string()));o["status"]=d.status();}catch(const std::exception&e){throw ApplicationError(409,e.what());}o["started_at"]=timestamp();store_.update("lab_orders",id,o);store_.audit(tech.value("id",std::string()),"lab_technician","lab_order.start",id,true,"");return Json{{"id",id},{"status",o["status"]}};}
    Json submitLabResults(const Json&tech,const std::string&id,const Json&j){Json o=assigned(tech,id);if(o.value("status",std::string())!="In Progress")throw ApplicationError(409,"Start the assigned investigation before entering results");if(!j.is_object()||!j.contains("results")||!j["results"].is_array()||j["results"].empty()||j["results"].size()>3)throw ApplicationError(400,"Provide one to three result entries");std::map<std::string,bool>seen;Json names=Json::array(),rows=Json::array();for(const Json&x:j["results"]){std::string name=field(x,"test_name",40),unit=field(x,"unit",30);if(name!="Haemoglobin"&&name!="WBC"&&name!="Platelets")throw ApplicationError(400,"Only CBC Haemoglobin, WBC and Platelets can be entered");if(seen[name])throw ApplicationError(400,"Duplicate CBC result");seen[name]=true;if(!x.contains("value")||!x["value"].is_number())throw ApplicationError(400,"Result value must be numeric");double v=x["value"].get<double>();if(!std::isfinite(v)||v<0.0||v>1000000.0)throw ApplicationError(400,"Result value is outside accepted numeric limits");rows.push_back(Json{{"id",newId()},{"patient_id",o["patient_id"]},{"order_id",id},{"technician_id",tech["id"]},{"test_name",name},{"value",v},{"unit",unit},{"reference_range",x.value("reference_range",Json(nullptr))},{"timestamp",timestamp()},{"status","Completed"}});names.push_back(name);}
        try{LaboratoryOrder d(id,o.value("patient_id",std::string()),o.value("doctor_id",std::string()),o.value("department",std::string()),o.value("test_name",std::string()),o.value("status",std::string()),o.value("technician_id",std::string()));d.complete(tech.value("id",std::string()));o["status"]=d.status();}catch(const std::exception&e){throw ApplicationError(409,e.what());}o["completed_at"]=timestamp();store_.updateAndInsertMany("lab_orders",id,o,"lab_results",rows);store_.audit(tech.value("id",std::string()),"lab_technician","lab_result.submit",id,true,"");return Json{{"order_id",id},{"status","Completed"},{"submitted",names}};}
};
}
#endif
